<script setup lang="ts">
import {nextTick,onMounted,onUnmounted,ref} from 'vue'
import {X} from 'lucide-vue-next'
const props=withDefaults(defineProps<{title?:string;label?:string;width?:number;closable?:boolean;busy?:boolean}>(),{width:520,closable:true})
const emit=defineEmits<{close:[]}>(),panel=ref<HTMLElement>();let previous:HTMLElement|null=null
function key(event:KeyboardEvent){if(event.key==='Escape'&&!props.busy){event.stopPropagation();emit('close')}if(event.key==='Tab'){const items=[...panel.value!.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),[tabindex="0"]')];if(!items.length)return;const index=items.indexOf(document.activeElement as HTMLElement);if(event.shiftKey&&index<=0){event.preventDefault();items.at(-1)?.focus()}else if(!event.shiftKey&&index===items.length-1){event.preventDefault();items[0]?.focus()}}}
onMounted(async()=>{previous=document.activeElement as HTMLElement;await nextTick();panel.value?.querySelector<HTMLElement>('input:not(:disabled),button:not(:disabled)')?.focus()});onUnmounted(()=>previous?.isConnected&&previous.focus())
</script>
<template><div class="electron-modal-mask" @click.self="!busy&&emit('close')" @keydown="key"><section @click.stop ref="panel" class="electron-modal" role="dialog" aria-modal="true" :aria-label="label||title" :style="{width:width+'px'}"><header v-if="title" class="electron-modal-header"><strong>{{title}}</strong><button v-if="closable" type="button" aria-label="关闭" :disabled="busy" @click="emit('close')"><X :size="16"/></button></header><div class="electron-modal-body"><slot/></div><footer v-if="$slots.footer" class="electron-modal-footer"><slot name="footer"/></footer></section></div></template>
<style scoped>
.electron-modal-mask{position:fixed;inset:0;z-index:3000;background:#0006;display:grid;place-items:center;padding:16px}.electron-modal{max-width:calc(100vw - 32px);max-height:calc(100vh - 32px);overflow:auto;background:var(--background);border:1px solid var(--control-border);border-radius:12px;color:var(--foreground);box-shadow:0 12px 48px #0004}.electron-modal-header{height:48px;border-bottom:1px solid var(--border);padding:0 20px;display:flex;align-items:center;justify-content:space-between;font-size:16px}.electron-modal-header button{background:transparent;border:0;padding:4px;color:inherit;cursor:pointer}.electron-modal-body{padding:24px 20px}.electron-modal-footer{border-top:1px solid var(--border);padding:16px 20px;display:flex;gap:12px;justify-content:flex-end}.electron-modal-footer :deep(button){height:32px;padding:0 15px;border-radius:4px;background:var(--secondary);font-size:14px}.electron-modal-footer :deep(button.primary){background:var(--primary);color:white}
</style>
